CREATE TABLE public.maintenance_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_number text NOT NULL, category text NOT NULL CHECK (category IN ('Wi-Fi','Plumbing','Electrical','Cleaning')), description text NOT NULL, status text NOT NULL DEFAULT 'Pending' CHECK (status IN ('Pending','Resolved')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.maintenance_tickets TO anon, authenticated;
GRANT UPDATE ON public.maintenance_tickets TO authenticated;
GRANT ALL ON public.maintenance_tickets TO service_role;
ALTER TABLE public.maintenance_tickets ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_ticket_board ON public.maintenance_tickets FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY owner_ticket_update ON public.maintenance_tickets FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'owner')) WITH CHECK (public.has_role(auth.uid(), 'owner'));
CREATE TABLE public.student_allotments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_name text NOT NULL, room_number text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.student_allotments TO authenticated;
GRANT ALL ON public.student_allotments TO service_role;
ALTER TABLE public.student_allotments ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_allotments ON public.student_allotments FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'owner')) WITH CHECK (public.has_role(auth.uid(), 'owner'));
CREATE TABLE public.rent_proofs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), allotment_id uuid NOT NULL REFERENCES public.student_allotments(id), payment_method text NOT NULL CHECK (payment_method IN ('UPI','Bank Transfer','Cash')), utr text NOT NULL DEFAULT '', file_path text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.rent_proofs TO authenticated;
GRANT ALL ON public.rent_proofs TO service_role;
ALTER TABLE public.rent_proofs ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_rent_proofs ON public.rent_proofs FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'owner'));
CREATE TABLE public.anonymous_feedback (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.anonymous_feedback TO authenticated;
GRANT ALL ON public.anonymous_feedback TO service_role;
ALTER TABLE public.anonymous_feedback ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_feedback ON public.anonymous_feedback FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'owner'));
CREATE POLICY owner_proof_files ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'rent-proofs' AND public.has_role(auth.uid(), 'owner'));